// src/playwright/extendTestWithMervScreenshots.ts
import { loadMervConfig as loadMervConfig3, MervLogger as MervLogger3 } from "merv-client";
import { tryAutoInstallMervChai } from "merv-client/chai";
import { AutomationTool } from "merv-client";
import { MervPlaywright as MervPlaywright2 } from "merv-client";
import { resetPluginStepScreenshotOrdinal } from "merv-client";
import { flushPendingPluginStepsAttachment } from "merv-client";
import { runInMervPlaywrightTestContext } from "merv-client";
import { setMervLogContext, clearMervLogContext } from "merv-client";
function testcaseLabel(testInfo) {
  try {
    const tp = testInfo.titlePath;
    if (typeof tp === "function") {
      const arr = tp();
      if (Array.isArray(arr) && arr.length) return arr.join(" \u203A ");
    } else if (Array.isArray(tp) && tp.length) {
      return tp.join(" \u203A ");
    }
  } catch {
  }
  return testInfo.title || "Test";
}
function extendTestWithMervScreenshots(baseTest) {
  return baseTest.extend({
    page: async ({ page }, use, testInfo) => {
      const cfg = loadMervConfig3();
      setMervLogContext({ suite: cfg.suiteTitle, testcase: testcaseLabel(testInfo) });
      MervLogger3.info("Hook: page setup \u2014 {}", testInfo.title);
      clearMervVideoFrames(testInfo);
      const attachToReport = cfg.screenshot;
      const video = cfg.video;
      if (!attachToReport && !video) {
        MervLogger3.debug(
          "Merv screenshots OFF (merv.screenshot=false or property not found). Set merv.screenshot=true for step PNGs, or merv.video=true for a stitched action video."
        );
      } else if (video && !attachToReport) {
        MervLogger3.info(
          "Merv video ON (screenshot OFF) \u2014 highlight frames feed the testcase video only; no step screenshots in the report."
        );
      } else if (video) {
        MervLogger3.info(
          "Merv video ON \u2014 action screenshots with element highlight; stitched video attached at test end (requires ffmpeg)."
        );
      }
      const activePage = wrapPageForMervScreenshots(page, testInfo, attachToReport, video);
      MervPlaywright2.setAutomationToolObject(AutomationTool.PLAYWRIGHT, activePage);
      try {
        await use(activePage);
      } finally {
        if (video) {
          await flushMervActionVideo(testInfo);
        }
        MervLogger3.info("Hook: page teardown \u2014 {}", testInfo.title);
        MervPlaywright2.setAutomationToolObject(null, null);
        clearMervVideoFrames(testInfo);
      }
    },
    request: async ({ request }, use, testInfo) => {
      await use(wrapRequestForMervApiDetails(request, testInfo));
    }
  }).extend({
    /** Ships {@link MervPlaywrightHandler} rows to the reporter via {@link TestInfo.attach} (cross-process). */
    _mervFlushPluginSteps: [
      async ({}, use, testInfo) => {
        resetPluginStepScreenshotOrdinal();
        const cfg = loadMervConfig3();
        if (cfg.chaiIntegration) {
          tryAutoInstallMervChai();
        }
        MervLogger3.info("Hook: test start \u2014 {}", testInfo.title);
        await runInMervPlaywrightTestContext(testInfo, () => use(void 0));
        MervLogger3.info("Hook: test end \u2014 {}", testInfo.title);
        await flushPendingPluginStepsAttachment(testInfo);
        await flushPendingMervExpectDetails(testInfo);
        clearMervLogContext();
      },
      { auto: true, scope: "test" }
    ]
  });
}

// src/playwright/mervPlaywrightHandler.ts
import {
  mervAddCustomStep,
  mervAddValidationStep,
  mervData,
  mervInfo,
  mervValidation
} from "merv-client";
var MervPlaywrightHandler = class {
  constructor(testInfo) {
    this.testInfo = testInfo;
  }
  testInfo;
  /** TEST_DATA row. Set last arg {@code screenshot: true} for a viewport PNG on this step. */
  async data(stepName, testdata, screenshot) {
    await mervData(this.testInfo, stepName, testdata, screenshot);
  }
  /** @deprecated Use {@link data}. */
  async addDataStep(stepName, testdata, screenshot) {
    return this.data(stepName, testdata, screenshot);
  }
  /** ASSERTION row. Optional last arg {@code screenshot: true} captures viewport PNG. */
  async validation(stepName, expected, actual, screenshot) {
    await mervValidation(this.testInfo, stepName, expected, actual, screenshot);
  }
  /** @deprecated Use {@link validation}. Legacy {@code testdata}/{@code prereq} args are ignored. */
  async addValidationStep(stepName, expected, actual, testdataOrScreenshot, prereqOrScreenshot, screenshot) {
    return mervAddValidationStep(
      this.testInfo,
      stepName,
      expected,
      actual,
      testdataOrScreenshot,
      prereqOrScreenshot,
      screenshot
    );
  }
  async addCustomStep(stepName, status, errorMessage) {
    await mervAddCustomStep(this.testInfo, stepName, status, errorMessage);
  }
  async info(infoToAdd) {
    await mervInfo(this.testInfo, infoToAdd);
  }
};

export {
  injectActionHighlight,
  removeActionHighlight,
  flushMervActionVideo,
  wrapPageForMervScreenshots,
  wrapExpectForMervScreenshots,
  extendTestWithMervScreenshots,
  MervPlaywrightHandler
};
